#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    int current = 0; // start at floor 0
    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long target = strtol(argv[i], &endptr, 10);
        if (target < 0 || target > 9) {
            puts("INVALID_FLOOR");
            continue;
        }
        while (current < target) {
            printf("MOVE_UP %d->%d\n", current, current + 1);
            ++current;
        }
        while (current > target) {
            printf("MOVE_DOWN %d->%d\n", current, current - 1);
            --current;
        }
        printf("ARRIVE %d\n", current);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current);
    return 0;
}
